import{_ as l,a0 as p,w as r,s as o,ao as d,I as i,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"何时需要关注 Linux 的内存用量？ | LCTT x X-CMD","titleTemplate":false,"description":"何时需要关注 Linux 的内存用量？ | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"何时需要关注 Linux 的内存用量？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"何时需要关注 Linux 的内存用量？ | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190513 When to be concerned about memory levels on Linux","title":"何时需要关注 Linux 的内存用量？","tag":"201907","desc":""},"relativePath":"201907/20190513 When to be concerned about memory levels on Linux.md","filePath":"[post].md"}'),u={name:"201907/20190513 When to be concerned about memory levels on Linux.md"};function h(b,s,c,m,g,k){const n=p("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="何时需要关注-linux-的内存用量" tabindex="-1">何时需要关注 Linux 的内存用量？ <a class="header-anchor" href="#何时需要关注-linux-的内存用量" aria-label="Permalink to “何时需要关注 Linux 的内存用量？”">​</a></h1><blockquote><p>Linux 上的内存管理很复杂。尽管使用率高但未必存在问题。你也应当关注一些其他的事情。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201907/06/173913n6rjbxwj6bfrjxwx.jpg" alt=""></p><p>在 Linux 上用光内存通常并不意味着存在严重的问题。为什么？因为健康的 Linux 系统会在内存中缓存磁盘活动，基本上占用掉了未被使用的内存，这显然是一件好事情。</p><p>换句话说，它不让内存浪费掉。使用空闲的内存增加磁盘访问速度，并且不占用运行中应用程序的内存。你也能够想到，使用这种内存缓存比起直接访问硬盘驱动器（HDD）快上数百倍，也比明显快于直接访问固态硬盘驱动。内存占满或几乎占满通常意味着系统正在尽可能高效地运行当中 —— 并不是运行中遇到了问题。</p><h3 id="缓存如何工作" tabindex="-1">缓存如何工作 <a class="header-anchor" href="#缓存如何工作" aria-label="Permalink to “缓存如何工作”">​</a></h3><p>磁盘缓存简单地意味着系统充分利用未使用的资源（空闲内存）来加速磁盘读取与写入。应用程序不会失去任何东西，并且大多数时间里能够按需求获得更多的内存。此外，磁盘缓存不会导致应用程序转而使用交换分区。反而，用作磁盘缓存的内存空间当被需要时会立即归还，并且磁盘内容会被更新。</p><h3 id="主要和次要的页故障" tabindex="-1">主要和次要的页故障 <a class="header-anchor" href="#主要和次要的页故障" aria-label="Permalink to “主要和次要的页故障”">​</a></h3><p>Linux 系统通过分割物理内存来为进程分配空间，将分割成的块称为“页”，并且映射这些页到每个进程的虚拟内存上。不再会用到的页也许会从内存中移除，尽管相关的进程还在运行。当进程需要一个没有被映射或没在内存中页时，故障便会产生。所以，这个“<ruby>故障<rt>fault</rt></ruby>”并不意味着“<ruby>错误<rt>error</rt></ruby>”而是“<ruby>不可用<rt>unavailables</rt></ruby>”，并且故障在内存管理中扮演者一个重要的角色。</p><p>次要故障意味着在内存中的页未分配给请求的进程，或未在内存管理单元中标记为出现。主要故障意味着页没有保留在内存中。</p><p>如果你想切身感受一下次要页故障和主要页故障出现的频率，像这样试一下 <code>ps</code> 命令。注意我们要的是与页故障和产生它的命令相关的项。输出中省略了很多行。<code>MINFL</code> 显示出次要故障的数目，而 <code>MAJFL</code> 表示了主要故障的数目。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -eo min_flt,maj_flt,cmd</span></span>
<span class="line"><span> MINFL  MAJFL CMD</span></span>
<span class="line"><span>230760    150 /usr/lib/systemd/systemd --switched-root --system --deserialize 18</span></span>
<span class="line"><span>     0      0 [kthreadd]</span></span>
<span class="line"><span>     0      0 [rcu_gp]</span></span>
<span class="line"><span>     0      0 [rcu_par_gp]</span></span>
<span class="line"><span>     0      0 [kworker/0:0H-kblockd]</span></span>
<span class="line"><span>   ...</span></span>
<span class="line"><span>   166     20 gpg-agent --homedir /var/lib/fwupd/gnupg --use-standard-socket --daemon</span></span>
<span class="line"><span>   525      1 /usr/libexec/gvfsd-trash --spawner :1.16 /org/gtk/gvfs/exec_spaw/0</span></span>
<span class="line"><span>  4966      4 /usr/libexec/gnome-terminal-server</span></span>
<span class="line"><span>  3617      0 bash</span></span>
<span class="line"><span>     0      0 [kworker/1:0H-kblockd]</span></span>
<span class="line"><span>   927      0 gdm-session-worker [pam/gdm-password]</span></span></code></pre></div><p>汇报单一进程，你可以尝试这样的命令（LCTT 译注：参数里面的 <code>1</code> 是要查看的进程的 PID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -o min_flt,maj_flt 1</span></span>
<span class="line"><span> MINFL  MAJFL</span></span>
<span class="line"><span>230064    150</span></span></code></pre></div><p>你也可以添加其他的显示字段，例如进程所有者的 UID 和 GID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -o min_flt,maj_flt,cmd,args,uid,gid 1</span></span>
<span class="line"><span> MINFL  MAJFL CMD                         COMMAND                       UID   GID</span></span>
<span class="line"><span>230064    150 /usr/lib/systemd/systemd -- /usr/lib/systemd/systemd --     0     0</span></span></code></pre></div><h3 id="多少才算满" tabindex="-1">多少才算满？ <a class="header-anchor" href="#多少才算满" aria-label="Permalink to “多少才算满？”">​</a></h3><p>一种较好的方法来掌握内存究竟使用了多少是用 <code>free -m</code> 命令。<code>-m</code> 选项指定了数字的单位是 <ruby>MiB<rt>mebibyte</rt></ruby> 而不是字节。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -m</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3244        3069          35          49         140         667</span></span>
<span class="line"><span>Swap:          3535           0        3535</span></span></code></pre></div><p>注意 <code>free</code>（未使用）的内存可能会不足，而 <code>available</code>（可用于启动新的应用）会显示更大的数量。这两者的区别值得我们去关注。<ruby>可用<rt>available</rt></ruby>意味着它可以在需要时恢复使用，而<ruby>空闲<rt>free</rt></ruby>意味着现在就能够使用。</p><h3 id="什么时候要担心" tabindex="-1">什么时候要担心 <a class="header-anchor" href="#什么时候要担心" aria-label="Permalink to “什么时候要担心”">​</a></h3><p>如果 Linux 系统上的性能表现良好 —— 应用程序响应度高，命令行没有显示出问题 —— 很可能系统状况良好。记住，一些应用也许会出于某种原因而变慢，但它不影响整个系统。</p><p>过多的硬故障也许表明确实存在问题，但要将其与观察到的性能相比较。</p><p>一个好的方法是当可用内存接近 0 或者“<ruby>用作交换<rt>swap used</rt></ruby>”项显著增长或波动时开始担心。如果“可用”项占总内存可用量的百分比合理，那么就无需担心，就像下面的例子那样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -m</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3244        3069          35          49         140         667</span></span>
<span class="line"><span>Swap:          3535           0        3535</span></span></code></pre></div><h3 id="linux-性能很复杂" tabindex="-1">Linux 性能很复杂 <a class="header-anchor" href="#linux-性能很复杂" aria-label="Permalink to “Linux 性能很复杂”">​</a></h3><p>抛开这些不说，Linux 系统上的内存可能会变满，并且性能可能会降低。当系统出现问题时不要仅将单一的内存使用报告作为指标。</p><p>Linux 系统的内存管理很复杂，因为它采取的措施需要确保系统资源得到最好的利用。不要受到一开始内存占满的欺骗，使你认为系统存在问题，但实际上并没有。</p><hr>`,29)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3394603/when-to-be-concerned-about-memory-levels-on-linux.html"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3394603/when-to-be-concerned-about-memory-levels-on-linux.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/LuuMing"},{default:t(()=>[...s[4]||(s[4]=[a("LuuMing",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const L=l(u,[["render",h]]);export{y as __pageData,L as default};
